const $=id=>document.getElementById(id),NS='http://www.w3.org/2000/svg';
const state={start:'#ea8b57',end:'#e7744a',fill:80};
function mix(a,b,u){const rgb=h=>[1,3,5].map(i=>parseInt(h.slice(i,i+2),16)),x=rgb(a),y=rgb(b);return `rgb(${x.map((v,i)=>Math.round(v+(y[i]-v)*u)).join(',')})`;}
function image(name,x,y,w,h,opacity=1){return `<image href="assets/${name}.png" x="${x}" y="${y}" width="${w}" height="${h}" opacity="${opacity}"/>`;}
function board(id){let cells='';const values=[1,0,2,0,3,0,3,1,0,2,2,0,0,1,0,0,2,3,0,1,3,1,0,2,0];for(let row=0;row<5;row++)for(let col=0;col<5;col++){const x=24+col*70.3,y=145+row*70.3,v=values[row*5+col];cells+=image(v?'tile':'ghost',x,y,60.8,60.8,v?1:.65);if(v){const dots=v===1?[[0,0]]:v===2?[[-10,-10],[10,10]]:[[-12,-12],[0,0],[12,12]];for(const [dx,dy]of dots)cells+=`<circle cx="${x+30.4+dx}" cy="${y+30.4+dy}" r="3.3" fill="#8c684a"/>`;}}
return `<svg xmlns="${NS}" viewBox="0 0 390 540" role="img" aria-label="${id==='current'?'Sadašnja':'Nova'} kombinacija boja u igri"><defs><linearGradient id="gradient-${id}" gradientUnits="userSpaceOnUse" x1="24" x2="366"><stop class="start"/><stop class="end" offset="1"/></linearGradient><clipPath id="reveal-${id}"><rect class="reveal" x="20" y="83" height="38"/></clipPath><filter id="shadow-${id}" x="-20%" width="140%" height="300%"><feGaussianBlur stdDeviation="3"/></filter></defs>${image('paper',0,0,390,844)}<path d="M0 0H390V111 Q195 151 0 111Z" fill="#fff" opacity=".17"/><path d="M8 114 Q195 143 382 114" fill="none" stroke="#b49478" opacity=".18" stroke-width="7" filter="url(#shadow-${id})"/><path d="M8 112 Q195 141 382 112" fill="none" stroke="#fff8ed" stroke-width="1.2"/>${image('close',31,53,24,24)}${image('trophy',104,53,27,27)}<text x="137" y="74" font-family="Baloo" font-size="17" fill="#b38160">3.064</text>${image('combo',227,52,27,27)}<text x="260" y="74" font-family="Baloo" font-size="18" fill="#e77449">x12</text>${image('backpack',324,48,33,33)}<path d="M28.375 98 Q195 113.936 361.625 98" fill="none" stroke="#f0e0d3" stroke-width="8.75" stroke-linecap="round"/><g ><path class="filled" d="M28.375 98 Q195 113.936 361.625 98" fill="none" stroke="url(#gradient-${id})" stroke-width="8.75" stroke-linecap="round"/></g><g class="bubbles"></g>${cells}</svg>`;}
for(const id of ['current','candidate'])$(id).querySelector('.phone').innerHTML=board(id);
function render(){for(const id of ['current','candidate']){const root=$(id),a=id==='current'?'#ffb561':state.start,b=id==='current'?'#e76813':state.end;root.querySelector('.start').setAttribute('stop-color',a);root.querySelector('.end').setAttribute('stop-color',b);root.querySelector('.strip').style.background=`linear-gradient(90deg,${a},${b})`;const t=state.fill/100;root.querySelector('.filled').setAttribute('d',`M28.375 98 Q${28.375+166.625*t} ${98+15.936*t} ${28.375+333.25*t} ${98+31.872*t*(1-t)}`);const bubbles=root.querySelector('.bubbles');bubbles.replaceChildren();for(const [u,dy,r]of [[.12,11,2.5],[.34,17,2],[.57,10,3],[.77,19,1.7],[.92,12,2.4]]){if(u>state.fill/100)continue;const n=document.createElementNS(NS,'circle');n.setAttribute('cx',24+342*u);n.setAttribute('cy',98+4*7.968*u*(1-u)-dy);n.setAttribute('r',r);n.setAttribute('fill',mix(a,b,u));n.setAttribute('opacity','.45');bubbles.append(n);}}$('amount').textContent=`${state.fill}%`;$('startHex').textContent=state.start.toUpperCase();$('endHex').textContent=state.end.toUpperCase();}
$('fill').addEventListener('input',event=>{state.fill=Number(event.target.value);render();});for(const key of ['start','end'])$(key).addEventListener('input',event=>{state[key]=event.target.value;render();});$('reset').addEventListener('click',()=>{state.start='#ea8b57';state.end='#e7744a';$('start').value=state.start;$('end').value=state.end;render();});render();
